                    if url.path == "/hooks/elevenlabs/decision":
                        try:
                            data = json.loads(self._body() or b"{}")
                            a = book.decide(int(data["alert_id"]), str(data["decision"]).lower(),
                                            by=str(data.get("by") or "voice agent"), channel="call",
                                            token=str(data.get("token", "")))
                        except PermissionError:
                            return self._send(403, b'{"ok":false}', "application/json")
                        except (KeyError, ValueError, TypeError) as e:
                            return self._send(400, json.dumps({"ok": False, "error": str(e)}).encode(),
                                              "application/json")
                        return self._send(200, json.dumps({"ok": True, "status": a.status}).encode(),
                                          "application/json")
                    if not self._authorized():
                        self.send_response(401)
                        self.send_header("WWW-Authenticate", 'Basic realm="ask-soony"')
                        self.end_headers()
                        return
                    if url.path.startswith("/alerts/") and url.path.endswith("/decide"):
                        alert_id = url.path[8:-7]
                        decision = parse_qs(self._body().decode()).get("decision", [""])[0]
                        if not alert_id.isdigit():
                            return self._send(404, b"not found")
                        try:
                            book.decide(int(alert_id), decision, by="dashboard", channel="dashboard")
                        except (KeyError, ValueError):
                            return self._send(400, b"invalid decision")
                        self.send_response(303)
                        self.send_header("Location", f"/alerts/{alert_id}")
                        self.end_headers()
                        return
                    return self._send(404, b"not found")
                finally:
                    store.db.close()
