    """Accept the call for its alert and follow it on the sideband (runs in a background thread)."""
    data = event.get("data", {})
    call_id = data.get("call_id")
    if not call_id:
        return
    key = os.environ.get("OPENAI_API_KEY", "")
    auth = {"Authorization": f"Bearer {key}"}
    store = Store(data_dir)
