            "model": os.environ.get("OPENAI_REALTIME_MODEL", "gpt-realtime-2.1"),
            "instructions": instructions(alert, contact_name),
            "audio": {"output": {"voice": os.environ.get("OPENAI_REALTIME_VOICE", "marin")}},
