"""
Small API for the decision inbox UI.

Reads the verifier's decision cards, stores human decisions, the autonomy mode and an event feed
under data/state/. Nothing about the customer is hardcoded here: the state file is passed through.
"""

import glob
import json
import logging
import os
from datetime import datetime, timezone
from pathlib import Path
from typing import Literal

from fastapi import FastAPI, HTTPException
from fastapi.responses import FileResponse
from fastapi.staticfiles import StaticFiles
from pydantic import BaseModel

from ask_soony import feed

ROOT = Path(__file__).resolve().parents[2]
FIXTURE = ROOT / "web" / "fixtures" / "sample_state.json"
FIXTURES = [FIXTURE, ROOT / "web" / "fixtures" / "sample_forecast_cards.json"]
DIST = ROOT / "web" / "dist"

log = logging.getLogger("uvicorn.error")
app = FastAPI(title="ask-soony dashboard")


def _store_dir() -> Path:
    return Path(os.environ.get("ASK_DATA_DIR") or ROOT / "data" / "store")


def _card_files() -> list[Path]:
    """ASK_SOONY_STATE (paths, globs, comma-separated) or every *cards*.json in the store."""
    spec = os.environ.get("ASK_SOONY_STATE")
    if spec:
        found: list[Path] = []
        for part in filter(None, (p.strip() for p in spec.split(","))):
            found += [Path(m) for m in sorted(glob.glob(part))]
        return [p for p in found if p.is_file()]
    return sorted(_store_dir().glob("*cards*.json"))


def _state_dir() -> Path:
    return Path(os.environ.get("ASK_SOONY_STATE_DIR") or ROOT / "data" / "state")


def _read(path: Path, default):
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return default


def _write(path: Path, value) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(".tmp")
import type { ActionKind, FeedEvent, State } from "./types";

async function json<T>(res: Response): Promise<T> {
  if (!res.ok) throw new Error(`${res.status} ${res.statusText}`);
  return res.json() as Promise<T>;
}

export const getState = () => fetch("/api/state").then((r) => json<State>(r));
export const getFeed = () => fetch("/api/feed").then((r) => json<FeedEvent[]>(r));

const post = (url: string, body: unknown) =>
  fetch(url, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  }).then((r) => json<unknown>(r));

export const postAction = (id: string, action: ActionKind, note?: string) =>
  post(`/api/cards/${encodeURIComponent(id)}/action`, { action, note });
export const postMode = (mode: State["mode"]) => post("/api/mode", { mode });
export type Evidence =
  | string
  | { doc_path?: string; page?: number; quote?: string; language?: string; translation?: string | null };

export type Option =
  | string
  | { action: string; cost?: string; effect?: string; recommended?: boolean };

export interface Message {
  to_role: string;
  to_email: string;
  subject: string;
  body: string;
}

export type ActionKind = "allow_once" | "allow_always" | "edit" | "dismiss";

export interface Card {
  id: string;
  title: string;
  edition: string;
  at_risk: number;
  part: string;
  system_says: string;
  paper_says: string;
  evidence: Evidence[];
  options: Option[];
  decision: unknown;
  messages: Message[];
  at_risk_if_acted: number;
  act_by: string | null;
  runs_dry: string | null;
  blocked_only: boolean;
  module?: string;
  source_file?: string;
  action_status?: { status: "sent" | "replied"; at: string; reply?: string };
  stage?: "before_arrival" | "after_dock";
  human_decision?: { action: ActionKind; note?: string | null; ts: string };
}

