  product: string;
  name: string;
  launch_date: string | null;
  day_one: number;
  packed: number;
  rate_per_hour: number;
  remaining: number;
  at_risk: number;
}

export interface State {
  source: string;
  mode: "ask" | "autonomous";
  now?: string;
  hours_left?: number;
  packing_ends?: string;
  editions: EditionRow[];
  parts: unknown[];
  cards: Card[];
}

export interface FeedEvent {
  at: string;
  actor: string;
  text: string;
  ref?: string;
}

