    cues = ['at the port', 'available for pick-up', 'CTA Hamburg', 'discharged']
    return any(any(cue in ev['value'] for cue in cues) for ev in evidence)

def option_is_urgent_collection(option):
    # Check for a message to DC site lead about urgent collection, ignore part specifics
    return (
        option.get('action', '').lower().startswith('message dc site lead: urgent: collect')
        and 'collect' in option.get('action', '').lower()
        and option.get('channel') == 'notify'
        and option.get('routine_type') == 'internal_note'
    )

